    # ### end Alembic commands ###
    # --- Change queue --------------------------------------------------------
    # Every write that can change availability, a price or a restriction marks
    # the affected (category, dates) as dirty for each channel connection of
    # the hotel, in the same transaction. Written only by these triggers, so no
    # code path (API, worker, import, manual SQL) can forget to notify channels.
    op.execute("""
        CREATE FUNCTION hms_channel_mark(p_hotel uuid, p_room_type uuid, p_start date, p_end date)
        RETURNS void LANGUAGE sql AS $$
            INSERT INTO channel_dirty_ranges (connection_id, room_type_id, start_date, end_date)
            SELECT c.id, p_room_type, p_start, p_end
            FROM channel_connections c
            WHERE c.hotel_id = p_hotel AND c.push_ari
              AND (p_end IS NULL OR p_end >= CURRENT_DATE - 1);
        $$;
    """)
    op.execute("""
        CREATE FUNCTION hms_channel_allocation_changed() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP IN ('UPDATE', 'DELETE') THEN
                PERFORM hms_channel_mark(OLD.hotel_id, (SELECT room_type_id FROM rooms WHERE id = OLD.room_id),
                                         lower(OLD.period), upper(OLD.period));
            END IF;
            IF TG_OP IN ('INSERT', 'UPDATE') THEN
                PERFORM hms_channel_mark(NEW.hotel_id, (SELECT room_type_id FROM rooms WHERE id = NEW.room_id),
                                         lower(NEW.period), upper(NEW.period));
            END IF;
            RETURN NULL;
        END $$;
    """)
    op.execute("""
        CREATE TRIGGER room_allocations_channel AFTER INSERT OR UPDATE OR DELETE ON room_allocations
        FOR EACH ROW EXECUTE FUNCTION hms_channel_allocation_changed();
    """)
    op.execute("""
        CREATE FUNCTION hms_channel_stay_changed() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP IN ('UPDATE', 'DELETE') THEN
                PERFORM hms_channel_mark(OLD.hotel_id, OLD.room_type_id, OLD.arrival, OLD.departure);
            END IF;
            IF TG_OP IN ('INSERT', 'UPDATE') THEN
                PERFORM hms_channel_mark(NEW.hotel_id, NEW.room_type_id, NEW.arrival, NEW.departure);
            END IF;
            RETURN NULL;
        END $$;
    """)
    op.execute("""
        CREATE TRIGGER reservation_rooms_channel
        AFTER INSERT OR DELETE OR UPDATE OF room_type_id, room_id, arrival, departure, occupies_inventory
        ON reservation_rooms FOR EACH ROW EXECUTE FUNCTION hms_channel_stay_changed();
    """)
    op.execute("""
        CREATE FUNCTION hms_channel_room_changed() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP IN ('UPDATE', 'DELETE') THEN
                PERFORM hms_channel_mark(OLD.hotel_id, OLD.room_type_id, NULL, NULL);
            END IF;
            IF TG_OP IN ('INSERT', 'UPDATE') THEN
                PERFORM hms_channel_mark(NEW.hotel_id, NEW.room_type_id, NULL, NULL);
            END IF;
            RETURN NULL;
        END $$;
    """)
    op.execute("""
        CREATE TRIGGER rooms_channel AFTER INSERT OR DELETE OR UPDATE OF is_active, room_type_id
        ON rooms FOR EACH ROW EXECUTE FUNCTION hms_channel_room_changed();
    """)
    op.execute("""
        CREATE FUNCTION hms_channel_room_type_changed() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            PERFORM hms_channel_mark(OLD.hotel_id, OLD.id, NULL, NULL);
            RETURN NULL;
        END $$;
    """)
    op.execute("""
        CREATE TRIGGER room_types_channel AFTER UPDATE OR DELETE ON room_types
        FOR EACH ROW EXECUTE FUNCTION hms_channel_room_type_changed();
    """)
    # Pricing-wide changes (plans, rules, taxes): every category, whole horizon.
    op.execute("""
        CREATE FUNCTION hms_channel_pricing_changed() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            PERFORM hms_channel_mark(CASE WHEN TG_OP = 'DELETE' THEN OLD.hotel_id ELSE NEW.hotel_id END,
                                     NULL, NULL, NULL);
            RETURN NULL;
        END $$;
    """)
