    # Daily rates change in bulk (a year of prices in one statement): one
    # range per category and statement, from the transition table.
    op.execute("""
        CREATE FUNCTION hms_channel_daily_rates_changed() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            INSERT INTO channel_dirty_ranges (connection_id, room_type_id, start_date, end_date)
            SELECT c.id, r.room_type_id, min(r.date), max(r.date) + 1
            FROM changed r
            JOIN channel_connections c ON c.hotel_id = r.hotel_id AND c.push_ari
            WHERE r.date >= CURRENT_DATE - 1
            GROUP BY c.id, r.room_type_id;
            RETURN NULL;
        END $$;
    """)
